const projects=[
{id:'INC-001',elapsedDays:180,name:'Residencial Aurora',sector:'Incorporações',budget:48,spent:24,progress:52,planned:50,days:360,owner:'Mariana Costa',risk:'Aprovações de fornecedores',action:'Manter acompanhamento semanal da obra.'},
{id:'INC-002',elapsedDays:180,name:'Parque das Oliveiras',sector:'Incorporações',budget:36,spent:22,progress:48,planned:60,days:300,owner:'Rafael Almeida',risk:'Atraso nas licenças e fundações',action:'Priorizar licenças e revisar o caminho crítico.'},
{id:'LOG-001',elapsedDays:149,name:'Modernização WMS Horizonte',sector:'Logística',budget:32,spent:19,progress:58,planned:62,days:240,owner:'Camila Rocha',risk:'Inconsistências no reporte e integração do WMS',action:'Validar os registros de custo e recuperar o cronograma do WMS.'},
{id:'LOG-002',elapsedDays:151,name:'Centro de Distribuição Sul',sector:'Logística',budget:24,spent:17,progress:75,planned:72,days:210,owner:'Pedro Santos',risk:'Integração dos sistemas',action:'Validar integração antes da operação assistida.'},
{id:'ENE-001',elapsedDays:208,name:'Usina Solar Alvorada',sector:'Energia',budget:42,spent:26,progress:65,planned:63,days:330,owner:'Beatriz Lima',risk:'Conexão à rede',action:'Confirmar janela de conexão com a distribuidora.'},
{id:'ENE-002',elapsedDays:206,name:'Expansão Solar Ventos do Norte',sector:'Energia',budget:58,spent:28,progress:44,planned:49,days:420,owner:'Lucas Ferreira',risk:'Licenciamento ambiental e entrega de módulos',action:'Validar licenças ambientais e a entrega dos módulos solares.'}
];
// Entradas sintéticas; não são dados operacionais do estudo de caso.
const signals=[{scope:1,openRisks:1,history:12,validated:true},{scope:4,openRisks:4,history:8,validated:true},{scope:3,openRisks:3,history:10,validated:false},{scope:1,openRisks:1,history:14,validated:true},{scope:2,openRisks:1,history:9,validated:true},{scope:3,openRisks:3,history:7,validated:true}];
projects.forEach((p,i)=>{Object.assign(p,signals[i]);Object.defineProperty(p,'status',{enumerable:true,get:()=>indicators(p).status});});
function indicators(p){
 const fraction=p.progress/100,ev=p.budget*fraction,pv=p.budget*p.planned/100;
 const spi=pv>0?ev/pv:null,cpi=p.spent>0?ev/p.spent:null;
 const eac=fraction>0?p.spent/fraction:null,duration=fraction>0?p.elapsedDays/fraction:null;
 const valid=Number.isFinite(spi)&&Number.isFinite(cpi),health=valid?Math.min(spi,cpi):null;
 return {ev,pv,spi,cpi,eac,duration,status:health===null?'Sem base':health>=.95?'Saudável':health>=.85?'Atenção':'Crítico'};
}
function criticalSignals(p){const m=indicators(p),signals=[];
 if(m.status==='Crítico')signals.push('Desempenho crítico (menor SPI/CPI < 0,85)');
 if(m.eac!==null&&m.eac>p.budget*1.2)signals.push('Projeção de custo mais de 20% acima do orçamento');
 if(m.duration!==null&&m.duration>p.days*1.2)signals.push('Projeção de prazo mais de 20% acima da base');
 if(!p.validated)signals.push('Dados pendentes de validação pelo PMO');
 return signals;
}
const number=(n,digits=1)=>Number.isFinite(n)?n.toLocaleString('pt-BR',{maximumFractionDigits:digits}):'—';
const durationText=n=>Number.isFinite(n)?number(Math.ceil(n),0)+' dias':'Sem base';
const changeText=(n,base,unit='')=>Number.isFinite(n)?(n-base>0?'+':'')+number(n-base)+(unit?' '+unit:''):'Sem base';
function comparison(title,items,format){
 const max=Math.max(1,...items.map(i=>Number.isFinite(i.value)?i.value:0));
 return `<figure class="comparison"><figcaption>${title}</figcaption>${items.map(i=>`<div class="compare-row"><div class="bar-label"><span>${i.label}</span><b>${format(i.value)}</b></div><div class="compare-track"><span class="compare-fill ${i.kind||''}" style="width:${Number.isFinite(i.value)?Math.max(0,i.value)/max*100:0}%" aria-hidden="true"></span></div></div>`).join('')}</figure>`;
}
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
function radar(p,cost=0,delay=0){
 const spi=p.progress/p.planned,cpi=p.budget*p.progress/100/p.spent;
 const schedule=clamp(1-spi+delay/100,0,1),expense=clamp(1-cpi+cost/100,0,1);
 const score=Math.round(100*(.35*schedule+.35*expense+.15*Math.min(p.scope/5,1)+.15*Math.min(p.openRisks/5,1)));
 const level=score>=25?'Elevado':score>=12?'Moderado':'Baixo';
 const reasons=[];if(spi<.95||delay>0)reasons.push('Avanço abaixo da linha de base ou aumento de prazo no cenário');if(cpi<.95||cost>0)reasons.push('Custo acima do valor agregado ou aumento de custo no cenário');if(p.scope>=3)reasons.push('Alterações de escopo recorrentes');if(p.openRisks>=3)reasons.push('Acúmulo de riscos abertos');if(!p.validated)reasons.push('Dados pendentes de validação pelo PMO');
 return {score,level,reasons};
}
function alerts(list){const ranked=[...list].sort((a,b)=>radar(b).score-radar(a).score);return `<section class="card alert-panel"><div class="card-head"><h2>Radar antecipativo · alertas ao PMO</h2><span class="tag">Regras ilustrativas</span></div><p class="subtitle">Índice demonstrativo de exposição, de 0 a 100. Não representa probabilidade nem previsão de IA treinada.</p><div class="alert-grid">${ranked.map(p=>{const r=radar(p);return `<article class="alert-item"><div class="card-head"><strong>${p.name}</strong><span class="status ${r.level==='Elevado'?'Critico':r.level==='Moderado'?'Atencao':''}">${r.level} · ${r.score}/100</span></div><p>${r.reasons.join(' · ')||'Sem sinal relevante pelas regras atuais.'}</p><p><b>Verificação PMO:</b> ${p.validated?'base sintética validada':'validar despesas e andamento antes de recomendar uma ação'}.</p><button class="button" data-detail="${p.id}">Ver evidências e ação →</button></article>`}).join('')}</div></section>`}
const money=n=>Number.isFinite(n)?n.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:1})+' mi':'Sem base';
const statusClass=s=>s==='Crítico'?'Critico':s==='Atenção'?'Atencao':'';
const badge=p=>`<span class="status ${statusClass(p.status)}">● ${p.status}</span>`;
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sector='Todos os setores',query='',statusFilter='Todos os status';
const selectedProjects=()=>projects.filter(p=>(sector==='Todos os setores'||p.sector===sector)&&(statusFilter==='Todos os status'||p.status===statusFilter));
const filtered=()=>selectedProjects().filter(p=>p.name.toLowerCase().includes(query.toLowerCase()));
const head=(eyebrow,title,description,extra='')=>`<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;
const filters=(search=false)=>`<div class="filters"><label class="filter-control">Divisão<select id="sector" aria-label="Filtrar por divisão">${['Todos os setores','Incorporações','Logística','Energia'].map(v=>`<option value="${v}" ${v===sector?'selected':''}>${v==='Todos os setores'?'Todas as divisões':v}</option>`).join('')}</select></label><label class="filter-control">Situação<select id="status" aria-label="Filtrar por situação">${['Todos os status','Saudável','Atenção','Crítico','Sem base'].map(v=>`<option value="${v}" ${v===statusFilter?'selected':''}>${v==='Todos os status'?'Todas as situações':v}</option>`).join('')}</select></label>${search?`<label class="filter-control">Nome do projeto<input type="search" id="search" aria-label="Buscar projeto" placeholder="Buscar projeto…" value="${escapeHTML(query)}"></label>`:''}<span class="stamp" role="status">Dados demonstrativos · ${search?filtered().length:selectedProjects().length} de ${projects.length} projetos</span></div>`;
function rows(list){return list.map(p=>{const m=indicators(p);return `<tr><td><button class="project-link" data-detail="${p.id}">${p.name}</button><small>${p.id}</small></td><td>${p.sector}</td><td>${badge(p)}</td><td>${money(p.budget)}</td><td>${money(m.eac)}</td><td>${durationText(m.duration)}</td><td>${p.planned}% / ${p.progress}%</td><td><button class="rowbutton" data-detail="${p.id}" aria-label="Ver detalhes de ${p.name}">↗</button></td></tr>`}).join('')}
function dashboard(){
 const list=selectedProjects(),count=list.length,budget=list.reduce((s,p)=>s+p.budget,0),spent=list.reduce((s,p)=>s+p.spent,0);
 const metrics=list.map(indicators),costs=metrics.filter(m=>m.eac!==null),times=metrics.filter(m=>m.duration!==null);
 const eac=count&&costs.length===count?costs.reduce((s,m)=>s+m.eac,0):null;
 const duration=times.length?times.reduce((s,m)=>s+m.duration,0)/times.length:null;
 const baseDuration=count?list.reduce((s,p)=>s+p.days,0)/count:null;
 const progress=count?list.reduce((s,p)=>s+p.progress,0)/count:null;
 const counts=['Saudável','Atenção','Crítico','Sem base'].map(v=>list.filter(p=>p.status===v).length);
 const flagged=list.filter(p=>criticalSignals(p).length),signalCount=flagged.reduce((s,p)=>s+criticalSignals(p).length,0);
 const share=n=>count?Math.round(n/count*100):0;
 return head('VISÃO EXECUTIVA','O portfólio, em perspectiva.','Indicadores calculados da base sintética. Projeções para apoiar a revisão do PMO.','<button class="button" id="export">↓ Exportar seleção</button>')+filters()+`
 <div class="kpis dashboard-kpis">
 <div class="card"><div class="kpi-title">Projetos na seleção <span class="kpi-icon">▦</span></div><div class="value">${count.toString().padStart(2,'0')}</div><div class="kpi-note">${projects.length} projetos na base demonstrativa</div></div>
 <div class="card"><div class="kpi-title">Sinais críticos <span class="kpi-icon">⚑</span></div><div class="value">${signalCount}</div><div class="kpi-note">${flagged.length} projetos sinalizados · ${counts[2]} em situação crítica</div></div>
 <div class="card"><div class="kpi-title">Custo final projetado <span class="kpi-icon">↗</span></div><div class="value projected-value">${money(eac)}</div><div class="kpi-note">Soma das projeções · ${eac===null?'sem base':changeText(eac,budget,'mi versus orçamento')}</div></div>
 <div class="card"><div class="kpi-title">Prazo médio projetado <span class="kpi-icon">◷</span></div><div class="value projected-value">${durationText(duration)}</div><div class="kpi-note">Média de ${times.length} projetos · base ${durationText(baseDuration)}</div></div>
 <div class="card"><div class="kpi-title">Orçamento e despesas <span class="kpi-icon">＄</span></div><div class="value projected-value">${money(budget)}</div><div class="kpi-note">Despesas realizadas: ${money(spent)}</div></div>
 <div class="card"><div class="kpi-title">Execução física média <span class="kpi-icon">◴</span></div><div class="value">${number(progress)}<small>${progress===null?'':'%'}</small></div><div class="kpi-note">Média simples dos projetos selecionados</div></div>
 </div>
 <div class="projection-note"><b>Projeções por ritmo constante.</b> Custo final = despesas ÷ execução realizada; prazo total = dias decorridos ÷ execução realizada. Execução expressa como fração. Não há modelo treinado, probabilidade ou precisão medida. ${list.some(p=>!p.validated)?'Há dados pendentes de validação na seleção.':''}</div>
 ${count?'':`<div class="notice" role="status">Nenhum projeto combina com os filtros. Ajuste a divisão ou a situação para explorar o portfólio.</div>`}
 <div class="grid"><section class="card"><div class="card-head"><h2>Saúde do portfólio</h2><span class="tag">SPI e CPI calculados</span></div><p class="subtitle">Situação derivada do menor índice de desempenho.</p><div class="chart"><div class="donut" style="background:${count?`conic-gradient(#39775a 0 ${counts[0]/count*100}%,#d6b16b ${counts[0]/count*100}% ${(counts[0]+counts[1])/count*100}%,#c97b6e ${(counts[0]+counts[1])/count*100}% ${(counts[0]+counts[1]+counts[2])/count*100}%,#9eaba7 ${(counts[0]+counts[1]+counts[2])/count*100}% 100%)`:'#dce9e3'}" role="img" aria-label="${counts[0]} saudáveis, ${counts[1]} em atenção, ${counts[2]} críticos, ${counts[3]} sem base"><div class="donut-center"><b>${count.toString().padStart(2,'0')}</b><span>projetos na seleção</span></div></div><div class="legend">${['Saudável','Atenção','Crítico','Sem base'].map((v,i)=>`<div class="legend-row"><span><i class="dot ${['','amber','red','neutral'][i]}"></i>${v}</span><b>${counts[i]} · ${share(counts[i])}%</b></div>`).join('')}</div></div></section>
 <section class="card"><div class="card-head"><h2>Investimento por divisão</h2><span class="tag">R$ milhões</span></div><p class="subtitle">Orçamento aprovado dos projetos selecionados.</p>${['Incorporações','Logística','Energia'].map(v=>{const n=list.filter(p=>p.sector===v).reduce((a,p)=>a+p.budget,0),percent=budget?n/budget*100:0;return `<div class="bar-row"><div class="bar-label"><span>${v}</span><b>${money(n)} · ${number(percent,0)}%</b></div><div class="bar"><i style="width:${percent}%"></i></div></div>`}).join('')}<div class="panel-note">Nenhum dado corresponde a projetos reais.</div></section></div>
 <section class="card critical-panel"><div class="card-head"><h2>Sinais que pedem revisão</h2><span class="tag">${signalCount} sinais · ${flagged.length} projetos</span></div><p class="subtitle">Regras: desempenho &lt; 0,85; projeção de custo ou prazo &gt; 20% acima da base; ou validação pendente. Um projeto pode ter vários sinais.</p><div class="alert-grid">${flagged.map(p=>`<article class="alert-item"><h3>${p.name}</h3><ul>${criticalSignals(p).map(v=>`<li>${v}</li>`).join('')}</ul><button class="button" data-detail="${p.id}">Revisar projeto →</button></article>`).join('')||'<p>Nenhum sinal crítico nesta seleção.</p>'}</div></section>
 <section class="card table-card"><div class="table-head"><div><h2>Radar de projetos</h2><p class="subtitle">Selecione o nome para comparar planejado e realizado.</p></div><a href="#projetos">Explorar projetos →</a></div><div class="table-scroll" role="region" aria-label="Indicadores e projeções dos projetos; tabela rolável" tabindex="0"><table><caption class="sr-only">Orçamentos, projeções e execução dos projetos demonstrativos</caption><thead><tr><th>PROJETO</th><th>DIVISÃO</th><th>SITUAÇÃO</th><th>ORÇAMENTO</th><th>CUSTO PROJETADO</th><th>PRAZO PROJETADO</th><th>EXECUÇÃO PLAN. / REAL.</th><th></th></tr></thead><tbody>${rows(list)||'<tr><td colspan="8">Sem projetos na seleção.</td></tr>'}</tbody></table></div></section>
 <div class="insight"><span class="insight-icon">✧</span><div><b>Do indicador à ação</b><p>Valide a base e revise escopo, capacidade e riscos antes de alterar o planejamento.</p></div><a href="#simulador" class="button" style="margin-left:auto">Simular cenário →</a></div>`;
}
function projectPage(){const list=filtered();return head('PORTFÓLIO','Projetos em movimento.','Seis iniciativas sintéticas. Três setores. Uma visão integrada.')+filters(true)+`<div class="project-grid">${list.map(p=>`<article class="card"><div class="card-head"><span class="eyebrow">${p.id}</span>${badge(p)}</div><h2>${p.name}</h2><p class="subtitle">${p.sector} · ${p.owner}</p><div class="project-metrics"><div><p class="subtitle">Orçamento</p><b>${money(p.budget)}</b></div><div><p class="subtitle">Prazo planejado</p><b>${p.days} dias</b></div></div><div class="bar-label"><span>Avanço físico</span><b>${p.progress}%</b></div><div class="bar"><i style="width:${p.progress}%"></i></div><p class="subtitle">Risco principal: ${p.risk}</p><p class="subtitle">Radar: ${radar(p).level} · ${radar(p).score}/100 · ${p.validated?'Dados validados':'Validação pendente'}</p><button class="button" data-detail="${p.id}">Explorar projeto ↗</button></article>`).join('')||'<p>Nenhum projeto encontrado. Ajuste os filtros.</p>'}</div>`}
function simulator(){return head('ANÁLISE DE CENÁRIOS','Antecipe o próximo movimento.','Explore o impacto de variações no custo e no prazo de um projeto.')+`<div class="sim-grid"><section class="card"><h2>Configure seu cenário</h2><p class="subtitle">Ajuste as premissas e veja a projeção em tempo real.</p><div class="field"><label for="sim-project">Projeto de referência</label><select id="sim-project">${projects.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></div><div class="field"><label for="cost">Variação no custo <b id="cost-label">+10%</b></label><input id="cost" type="range" aria-valuetext="" min="-20" max="50" value="10" step="1"><div class="bar-label"><span>−20%</span><span>+50%</span></div></div><div class="field"><label for="delay">Variação no prazo <b id="delay-label">+15%</b></label><input id="delay" type="range" aria-valuetext="" min="-20" max="50" value="15" step="1"><div class="bar-label"><span>−20%</span><span>+50%</span></div></div><button class="button" id="reset">↺ Restaurar cenário</button></section><section class="card result" id="sim-result" aria-live="polite"></section></div><div class="insight"><span class="insight-icon">◎</span><div><b>Uma hipótese para apoiar a conversa</b><p>O cenário recalcula custo, prazo e o índice ilustrativo do radar. O PMO verifica os alertas; não há modelo treinado ou probabilidade estimada.</p></div></div>`}
function methodology(){return head('ATIVIDADE 3 · IA APLICADA','A lógica por trás do radar.','Do desvio identificado ao alerta verificado pelo PMO.')+`<div class="notice">Baseado na Atividade 3 do estudo de caso Grupo Vanguarda, páginas 4–5. Todos os projetos e dados deste protótipo são sintéticos. A IA preditiva é a aplicação proposta; a demonstração usa regras transparentes, sem modelo treinado.</div><div class="method-grid"><section class="card"><div class="eyebrow">01 · PROBLEMA</div><h3>Identificar desvios antes que se agravem</h3><p>A atividade relata identificação tardia de atrasos, custos excessivos e inconsistências nas informações do WMS, das obras residenciais e da expansão solar. O radar concentra sinais para apoiar a análise do PMO.</p></section><section class="card"><div class="eyebrow">02 · FUNCIONAMENTO PROPOSTO</div><h3>IA preditiva com acompanhamento humano</h3><p>Padronizar e validar dados → comparar planejado e realizado → analisar tendências e desvios com IA → emitir alertas → PMO verificar evidências → recomendar ações corretivas aos gestores.</p><p>O PMO valida os alertas e acompanha as ações; o sistema não aprova investimentos nem substitui a decisão formal.</p></section><section class="card"><div class="eyebrow">03 · DADOS NECESSÁRIOS</div><h3>Qualidade antes da previsão</h3><p>Cronogramas previstos e realizados; orçamentos e despesas; percentual de execução; alterações de escopo; registros de riscos; histórico de projetos.</p><p>Na implantação, validar completude, datas de atualização, rastreabilidade e consistência entre fontes. O protótipo mostra uma pendência de validação no WMS. Histórico e responsáveis são fictícios.</p></section><section class="card"><div class="eyebrow">04 · BENEFÍCIOS ESPERADOS</div><h3>Agilidade, transparência e previsibilidade</h3><p>Antecipar problemas, agilizar ações corretivas, reduzir riscos de atraso e custo excessivo e melhorar a transparência para diretoria e Conselho. São benefícios esperados pela atividade, não resultados medidos neste protótipo.</p></section><section class="card"><div class="eyebrow">05 · REGRAS DO PROTÓTIPO</div><h3>Um índice explicável, não uma probabilidade</h3><div class="formula">EV = orçamento × avanço físico / 100<br>PV = orçamento × avanço planejado / 100<br>SPI = EV / PV · CPI = EV / despesas<br>Radar = 100 × (0,35 × desvio de prazo<br>+ 0,35 × desvio de custo<br>+ 0,15 × escopo + 0,15 × riscos)</div><p>Desvios = 1 − SPI/CPI, acrescidos da variação do cenário, limitados entre 0 e 1. Escopo e riscos = contagem / 5, limitada a 1. Arredondamento inteiro; baixo &lt; 12, moderado de 12 a 24, elevado ≥ 25. Pesos e faixas são escolhas demonstrativas, não definidos pelo PDF.</p><p>Status operacional: menor SPI/CPI ≥ 0,95 é saudável; de 0,85 a 0,95 é atenção; abaixo de 0,85 é crítico. O radar é um sinal separado para investigar exposição.</p></section><section class="card"><div class="eyebrow">06 · SIMULAÇÃO & LIMITES</div><h3>Hipóteses para discussão do PMO</h3><div class="formula">Custo = orçamento × (1 + variação / 100)<br>Prazo = dias × (1 + variação / 100)</div><p>O cenário recalcula o índice ilustrativo sem alterar a base. Não há treinamento, inferência de machine learning ou acurácia validada. Para implantar a IA proposta, serão necessários histórico real validado, avaliação temporal, calibração, monitoramento e revisão humana.</p><p>O Dashboard soma orçamentos, despesas e custos projetados, e usa média simples do avanço e dos prazos. As situações são calculadas a cada consulta a partir de SPI e CPI, sem rótulos fixos. Fonte: vanguarda_pdf.pdf, Atividade 3, páginas 4–5. SPI/CPI, índice e seis projetos são recursos acrescentados para demonstrar o fluxo.</p></section></div><section class="card projection-method"><div class="eyebrow">07 · PROJEÇÕES DO DASHBOARD</div><h3>Extrapolar o ritmo atual</h3><div class="formula">Fração realizada = execução realizada / 100<br>Custo final projetado = despesas / fração realizada = orçamento / CPI<br>Prazo total projetado = dias decorridos / fração realizada</div><p>Os dias decorridos são entradas sintéticas do retrato atual. A projeção de prazo assume execução linear no ritmo físico observado; não considera caminho crítico, sazonalidade ou dependências. Valores são calculados sem arredondar intermediários; a interface arredonda dias para cima.</p><p>Na seleção, os custos projetados são somados e o prazo projetado é uma média aritmética, não um prazo de conclusão da holding. Execução nula implica ausência de base para projetar. Sinais críticos contam cada regra acionada: menor SPI/CPI &lt; 0,85, custo ou prazo projetado &gt; 20% acima da base, ou validação pendente. Um projeto pode acionar várias regras; estas são escolhas demonstrativas.</p><p>Sem histórico real e validação fora da amostra, não há métricas de precisão ou acurácia para reportar.</p></section>`}
function updateSim(){const p=projects.find(p=>p.id===document.querySelector('#sim-project').value),c=+document.querySelector('#cost').value,d=+document.querySelector('#delay').value;const sign=n=>(n>=0?'+':'')+n+'%';document.querySelector('#cost-label').textContent=sign(c);document.querySelector('#delay-label').textContent=sign(d);document.querySelector('#cost').setAttribute('aria-valuetext',sign(c));document.querySelector('#delay').setAttribute('aria-valuetext',sign(d));document.querySelector('#sim-result').innerHTML=`<div class="eyebrow" style="color:#bfdaa9">RESULTADO DO CENÁRIO</div><h3>${p.name}</h3><p class="subtitle">Custo total simulado</p><div class="result-number">${money(p.budget*(1+c/100))}</div><p>${money(Math.abs(p.budget*c/100))} ${c>=0?'acima':'abaixo'} do orçamento de ${money(p.budget)}.</p><hr><p class="subtitle">Prazo total simulado</p><div class="result-number">${Math.round(p.days*(1+d/100))} <small style="font-size:16px">dias</small></div><p>${Math.abs(Math.round(p.days*d/100))} dias ${d>=0?'a mais':'a menos'} em relação à base de ${p.days} dias.</p><hr><p class="subtitle">Radar ilustrativo · exposição no cenário</p><div class="result-number">${radar(p,c,d).score}<small style="font-size:16px">/100 · ${radar(p,c,d).level}</small></div><p>Base: ${radar(p).score}/100. O índice usa desvios, escopo e riscos abertos.</p><p>${radar(p,c,d).reasons.join(' · ')||'Sem sinal relevante pelas regras atuais.'}</p><hr><b>${c>20||d>20?'Impacto elevado no cenário':c>0||d>0?'Revisão de premissas sugerida':'Cenário de redução'}</b><p>Discuta viabilidade, capacidade de execução e riscos antes de rever a linha de base.</p>`}
function detail(id){
 const p=projects.find(p=>p.id===id);if(!p)return;const m=indicators(p);
 document.querySelector('#detail-content').innerHTML=`<div class="eyebrow">${p.id} · DADOS DEMONSTRATIVOS</div><h1 id="detail-title">${p.name}</h1>${badge(p)}<p>${p.sector} · Responsável fictício: ${p.owner}</p>
 <div class="detail-metrics"><div><span>Orçamento aprovado</span><b>${money(p.budget)}</b></div><div><span>Despesas realizadas</span><b>${money(p.spent)}</b></div><div><span>Prazo planejado</span><b>${p.days} dias</b></div><div><span>Dias decorridos</span><b>${p.elapsedDays} dias</b></div><div><span>Execução planejada</span><b>${p.planned}%</b></div><div><span>Execução realizada</span><b>${p.progress}%</b></div><div><span>SPI · desempenho de prazo</span><b>${number(m.spi,2)}</b></div><div><span>CPI · desempenho de custo</span><b>${number(m.cpi,2)}</b></div></div>
 <h2>Planejado e realizado na data de referência</h2><p class="subtitle">Um retrato da base demonstrativa; não representa uma série histórica.</p><div class="detail-charts">
 ${comparison('Execução física (%)',[{label:'Planejada',value:p.planned,kind:'planned'},{label:'Realizada',value:p.progress,kind:'actual'}],v=>number(v)+'%')}
 ${comparison('Valores na data de referência (R$ mi)',[{label:'Valor planejado (PV)',value:m.pv,kind:'planned'},{label:'Valor entregue (EV)',value:m.ev,kind:'actual'},{label:'Despesas realizadas (AC)',value:p.spent,kind:'expense'}],money)}
 ${comparison('Custo total: base e projeção',[{label:'Orçamento aprovado',value:p.budget,kind:'planned'},{label:'Custo final projetado',value:m.eac,kind:'forecast'}],money)}
 ${comparison('Prazo total: base e projeção',[{label:'Prazo planejado',value:p.days,kind:'planned'},{label:'Prazo total projetado',value:m.duration,kind:'forecast'}],durationText)}
 </div><p class="subtitle">PV e EV são valores equivalentes ao avanço físico; PV não representa um cronograma de pagamentos. Cada gráfico usa sua própria escala e exibe os valores numéricos.</p>
 <div class="projection-note"><b>Estimativas por ritmo constante.</b> Custo projetado: ${money(m.eac)} (${changeText(m.eac,p.budget,'mi')}). Prazo projetado: ${durationText(m.duration)} (${m.duration===null?'sem base':changeText(Math.ceil(m.duration),p.days,'dias')}). As fórmulas pressupõem continuidade do ritmo e da relação entre despesas e execução, sem novas mudanças de escopo. Não são previsões validadas de IA.</div>
 <h3>Riscos e sinais monitorados</h3><p>${p.risk}</p><p>${p.openRisks} riscos abertos · ${p.scope} alterações de escopo.</p><ul class="detail-signals">${criticalSignals(p).map(v=>`<li>${v}</li>`).join('')||'<li>Sem sinal crítico pelas regras atuais.</li>'}</ul>
 <h3>Qualidade dos dados</h3><p>${p.validated?'Registros sintéticos validados.':'Registros pendentes de validação: revisar despesas e andamento antes de utilizar as projeções.'} Histórico ilustrativo de ${p.history} projetos; não há treinamento de modelo.</p>
 <h3>Próxima ação sugerida ao PMO</h3><p>${p.action}</p>`;
 dialogOpener=document.activeElement;document.querySelector('dialog').showModal();document.querySelector('#close-detail').focus();
}
function exportData(){
 const fmt=n=>Number.isFinite(n)?String(n).replace('.',','):'';
 const csv='\uFEFF'+['ID;Projeto;Divisão;Situação;Orçamento (R$ mi);Despesas (R$ mi);Prazo planejado (dias);Dias decorridos;Execução planejada (%);Execução realizada (%);Custo projetado (R$ mi);Prazo projetado (dias);SPI;CPI;Dados',...selectedProjects().map(p=>{const m=indicators(p);return [p.id,p.name,p.sector,p.status,fmt(p.budget),fmt(p.spent),p.days,p.elapsedDays,p.planned,p.progress,fmt(m.eac),m.duration===null?'':Math.ceil(m.duration),fmt(m.spi),fmt(m.cpi),'Demonstrativos'].join(';')})].join('\n');
 const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='vanguarda-portfolio-demonstrativo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function bindDetails(root=document){root.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));}
function refreshProjectCards(){
 const template=document.createElement('template');template.innerHTML=projectPage();
 const grid=document.querySelector('.project-grid');grid.innerHTML=template.content.querySelector('.project-grid').innerHTML;document.querySelector('.stamp').textContent=template.content.querySelector('.stamp').textContent;bindDetails(grid);
}
function render(){
 const page=location.hash.slice(1)||'dashboard',valid=['dashboard','projetos','simulador','metodologia'].includes(page)?page:'dashboard';
 document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===valid);if(a.dataset.page===valid)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 document.title=({dashboard:'Dashboard',projetos:'Projetos',simulador:'Simulador',metodologia:'Metodologia'}[valid])+' · Vanguarda — Radar PMO';
 document.querySelector('#main').innerHTML=({dashboard,projetos:projectPage,simulador:simulator,metodologia:methodology}[valid])();
 document.querySelector('#sector')?.addEventListener('change',e=>{sector=e.target.value;if(valid==='projetos')refreshProjectCards();else{render();document.querySelector('#sector').focus();}});
 document.querySelector('#status')?.addEventListener('change',e=>{statusFilter=e.target.value;if(valid==='projetos')refreshProjectCards();else{render();document.querySelector('#status').focus();}});
 document.querySelector('#search')?.addEventListener('input',e=>{query=e.target.value;refreshProjectCards();});
 bindDetails();document.querySelector('#export')?.addEventListener('click',exportData);
 if(valid==='simulador'){
  ['sim-project','cost','delay'].forEach(id=>document.getElementById(id).addEventListener('input',updateSim));
  document.querySelector('#reset').onclick=()=>{document.querySelector('#sim-project').value=projects[0].id;document.querySelector('#cost').value=10;document.querySelector('#delay').value=15;updateSim();};updateSim();
 }
}
let dialogOpener=null;
const dialog=document.querySelector('#detail');
document.querySelector('#close-detail').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>{if(dialogOpener?.isConnected)dialogOpener.focus();});
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();document.querySelector('#main').focus();});
const reducedTransparency=window.matchMedia('(prefers-reduced-transparency: reduce)');
let appearancePreference=null;
try{appearancePreference=localStorage.getItem('vanguarda-appearance');}catch{}
function applyAppearance(){
 const solid=appearancePreference==='solid'||(appearancePreference!=='glass'&&reducedTransparency.matches);
 document.documentElement.dataset.appearance=solid?'solid':'glass';
 const button=document.querySelector('#appearance-toggle');button.setAttribute('aria-pressed',String(solid));
 button.title=solid?'Ativar cartões translúcidos':'Ativar aparência sólida, sem transparência ou desfoque';
}
document.querySelector('#appearance-toggle').addEventListener('click',()=>{
 appearancePreference=document.documentElement.dataset.appearance==='solid'?'glass':'solid';
 try{localStorage.setItem('vanguarda-appearance',appearancePreference);}catch{}
 applyAppearance();
});
reducedTransparency.addEventListener?.('change',applyAppearance);
window.addEventListener('hashchange',()=>{render();document.querySelector('#main').focus();window.scrollTo({top:0,behavior:'instant'});});
applyAppearance();render();
